contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public function with parameters: owner caller flag, recipient, and an amount to fund C
    function run(bool callAsOwner, address payable recipient, uint256 fundAmount) public payable {
        require(recipient != address(0));
        // fundAmount must be supplied from this contract's balance when calling c's fallback
        if (fundAmount > 0) {
            require(address(this).balance >= fundAmount);
            // send Ether to C to set up its balance
            (bool sent, ) = address(c).call{value: fundAmount}("");
            require(sent);
        }

        // Read state before call
        address preOwner = c.owner();
        uint256 beforeBalance = address(c).balance;
        uint256 testerBefore = address(this).balance;

        bool willRevert;
        // Decide who should be msg.sender: if callAsOwner true, we only proceed when preOwner == address(this)
        // But we cannot change msg.sender in Solidity; however the deployment model states InvMutTest is msg.sender for calls.
        // So enforce precondition that matches desired caller role when testing owner path; otherwise test non-owner path.
        if (callAsOwner) {
            // require that this contract is the owner so the call should succeed
            require(preOwner == address(this));
            // call should NOT revert
            try c.withdrawAll(recipient) {
                willRevert = false;
            } catch {
                willRevert = true;
            }
        } else {
            // require that this contract is NOT the owner so the call should revert
            require(preOwner != address(this));
            try c.withdrawAll(recipient) {
                willRevert = false;
            } catch {
                willRevert = true;
            }
        }

        // Read state after call
        uint256 afterBalance = address(c).balance;
        uint256 testerAfter = address(this).balance;

        // General rule asserted for all inputs:
        // - If caller was owner (callAsOwner and preOwner == this), call must not revert, C's balance goes to 0, and recipient (externally observed by change in this contract's balance only when recipient == this) receives the funds.
        // - If caller was not owner (not callAsOwner and preOwner != this), call must revert and C's balance unchanged.
        assert(
            (callAsOwner && preOwner == address(this) && willRevert == false && afterBalance == 0)
            ||
            (!callAsOwner && preOwner != address(this) && willRevert == true && afterBalance == beforeBalance)
        );
    }

    receive() external payable {}
}

