    // params: caller (as address), recipient, amount to fund contract, and a boolean indicating whether to call withdraw
    function run(address caller, address payable recipient, uint256 fundAmount, bool doWithdraw) public payable {
        require(address(this).balance >= fundAmount);

        // fund the contract c by sending Ether from this test contract to c
        (bool s,) = address(c).call{value: fundAmount}("");
        require(s);

        // record balances before
        uint256 beforeC = address(c).balance;
        uint256 beforeRecipient = recipient.balance;

        // attempt withdrawAll from caller by making c.withdrawAll called by this contract but using caller via a low-level call
        bool reverted;
        if (doWithdraw) {
            // perform call as this contract; since the checker deploys c and run is single tx, msg.sender for c will be this test contract
