        } else {
            reverted = true; // no attempt to withdraw
        }

        // read public owner and balances after
        address owner = c.owner();
        uint256 afterC = address(c).balance;
        uint256 afterRecipient = recipient.balance;

        // General rule:
        // If the call did not revert then msg.sender (the InvMutTest contract) must have been owner and the contract transferred all its balance to recipient (so c balance is zero and recipient gained exactly beforeC)
        // Otherwise, if it reverted or was not attempted, the contract balance is unchanged.
        assert( (!reverted && owner == address(this) && afterC == 0 && afterRecipient - beforeRecipient == beforeC)
                || (reverted && afterC == beforeC) );
    }

