    // params: caller (address attempted to act as msg.sender by making the call), recipient, amount to send to contract beforehand
    function run(address caller, address payable recipient, uint256 fund) public payable {
        require(address(this).balance >= fund);
        // fund the contract c from this test contract
        (bool okFund,) = address(c).call{value: fund}("");
        // After funding, record balance
        uint256 before = address(c).balance;

        // Attempt withdrawAll as 'caller'. Because the checker runs in a single tx with msg.sender = this contract,
        // we emulate calls from different addresses by relying on the fact that only c.owner getter is visible.
        // However the actual call will originate from this contract; to express the property universally we
        // check two cases depending on whether 'caller' equals c.owner():
        bool reverted;
        // perform the call: since we cannot change msg.sender, we still call withdrawAll and observe whether it reverts
