        // We capture whether the call reverts.
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = address(c).balance;
        address ownerAddr = c.owner();

        // General rule: if the contract's owner equals this test contract (msg.sender for calls to c), withdrawAll must succeed and drain the contract;
