    // and a flag indicating whether the test should attempt withdrawal (always attempts).
    function run(address ownerAddr, address payable recipient, uint256 fundAmount) public payable {
        require(address(this).balance >= fundAmount);

        // Deploy-time: c is already deployed fresh by the checker with some owner; we can only interact.
        // First, fund c by sending Ether from this contract to c (use transfer via plain call)
        // Note: must ensure this contract has enough balance (checked above).
        (bool sent, ) = address(c).call{value: fundAmount}("");
